// One anchor per resource placement, shared by the lesson page and the Evidence Library so each links to the other.
export const resourceAnchor=(lesson,index)=>`r-${lesson.replace(/\./g,'-')}-${index+1}`;
const withMeta=(lesson,item,index)=>({...item,category:item.role,level:item.role,lesson,module:Number(lesson.split('.')[0]),anchor:resourceAnchor(lesson,index)});
export const readingsFor=(moduleId,lessonId)=>(resourcePlan[`${moduleId}.${lessonId}`]||[]).map((item,index)=>withMeta(`${moduleId}.${lessonId}`,item,index));
const placements=Object.entries(resourcePlan).flatMap(([lesson,items])=>items.map((item,index)=>withMeta(lesson,item,index)));
// The library lists each source once, at its primary home, with the other lessons that also use it.
export const resources=placements.filter(item=>!item.crossRef).map(item=>({...item,id:item.anchor,alsoIn:placements.filter(p=>p.crossRef&&p.url===item.url)}));
export const primaryFor=item=>resources.find(p=>p.url===item.url);
export const sources=resources.map(item=>[`${item.title} · ${item.organisation}`,item.url]);
